    }
}

afterExample:
package test;

import org.eclipse.jface.text.ITextOperationTarget;

public class MyClass {
    private int fOperationCode;

    public void update() {
        if (fOperationCode == ITextOperationTarget.UNDO || fOperationCode == ITextOperationTarget.REDO)
            return;
    }
}

