package test;

import org.eclipse.jface.text.ITextOperationTarget;

public class MyClass {
    private int fOperationCode;

    public void update() {
        if (fOperationCode == ITextOperationTarget.UNDO) // Should not change
            return;
        if (fOperationCode == 1) // Should not change
            return;
    }
}
